action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger");
  const html = await r.text();
  const m = html.match(/openapi[^"\x27 ]*\.json|url\s*[:=]\s*["\x27][^"\x27]+["\x27]/g);
  console.log("matches:", m);
  const guess = m ? m[m.length-1].replace(/^.*["\x27]/,"").replace(/["\x27]$/,"") : null;
  if (guess) {
    const specUrl = guess.startsWith("http") ? guess : "http://backend:4000/api/v1/swagger/" + guess;
    const sr = await fetch(specUrl);
    const j = await sr.json();
    const keys = Object.keys(j.paths||{}).filter(k=>k.includes("email"));
    console.log("spec:", specUrl, "emailPaths:", keys);
    const body = j.paths["/auth/init-email-login"].post.requestBody.content["application/json"].schema;
    console.log("init schema ref:", JSON.stringify(body));
    console.log(JSON.stringify(j.components.schemas[body.$ref ? body.$ref.replace("#/components/schemas/","") : ""], null, 1).slice(0,800));
  }
})();
'

